export function baseShotHit(name,n){const table={エンラ:[[1,1],[2,3],[3,5]],ヌエ:[[4,7],[5,10],[6,14]],ダタラ:[[2,2],[3,3],[4,4]],カサネ:[[1,2],[2,4],[3,6]],ハクメン:[[2,2],[3,3],[4,5]],ウワン:[[1,1],[2,2],[3,4]],ドドメ:[[1,1],[2,3],[3,5],[4,7]],キヨヒメ:[[3,0],[5,0]],ツエツキ:[[2,0],[3,0],[4,0]],ヒカギリ:[[1,2],[2,4]],ロクロ:[[0,0],[1,1],[2,3],[3,5]],ダイダラ:[[2,4],[4,9]],モウリョウ:[[6,10]],バク:[[2,0],[3,0]],ミツメ:[[1,1],[2,2],[3,3]],カシャ:[[4,6],[6,10]],ヒダル:[[3,3],[5,3]]};return (table[name]||[]).filter(x=>x[0]<=n).at(-1)?.[1]??0;}

